//! Gold: `locator` is 1:1 with the live `harness/electronics/locator.py`.
//!
//! `tests/fixtures/gold/locator_v1.json` was generated by
//! `scripts/gold_locator.py` — `locate` cases feed a mock document (TOC +
//! per-page texts and extracted table grids) through
//! `locate_pin_definition_pages`, kernel cases call the pure readers. The
//! `find_tables()` layer is PDF-layer: the port receives the same row grids
//! the reference extracts, `None`-cellled as `extract()` returns them.
//!
//! The cases pin the traps the locator exists for: definition tables only —
//! never ballout figures, legends or alternate-function tables;
//! `(continued)` walk-back; consecutive definition pages stopping at the
//! first gap; package columns matched by identity never by cousin name;
//! qualified-variant withholding; the TI borderless single-package
//! relaxation (3 pages, still fail-closed downstream); JEDEC corroboration
//! counting distinct identifiers in the selected column; and
//! `validate_physical_pin_truth`'s duplicate/unique/LQFP-range gates.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::locator::{
    classify_title, locate_pin_definition_pages, match_package_column, package_headers,
    package_pin_count, toc_entries, validate_physical_pin_truth, PageInput,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/locator_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// `extract()` grids: rows of `Option<String>` cells.
type Grid = Vec<Vec<Option<String>>>;

fn grids_of(v: &Value) -> Vec<Grid> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|grid| serde_json::from_value(grid.clone()).unwrap())
        .collect()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "locate" => {
                let input = &case["input"];
                let texts: Vec<String> = input["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p["text"].as_str().unwrap().to_string())
                    .collect();
                let tables: Vec<Option<Vec<Grid>>> = input["page_tables"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|entry| entry.get("tables").filter(|t| !t.is_null()).map(grids_of))
                    .collect();
                let pages: Vec<PageInput<'_>> = texts
                    .iter()
                    .zip(&tables)
                    .map(|(text, tables)| PageInput {
                        text,
                        tables: tables.as_deref(),
                    })
                    .collect();
                let toc: Vec<Value> = input["toc"].as_array().unwrap().clone();
                let result = locate_pin_definition_pages(
                    &pages,
                    &toc,
                    input["document_id"].as_str().unwrap(),
                    input["requested_package"].as_str().unwrap(),
                    input["expected_package_pins"].as_i64().unwrap(),
                    input["source_path"].as_str().unwrap(),
                    input["text_section_single_package"]
                        .as_bool()
                        .unwrap_or(false),
                );
                let expected = &case["expected"];
                if expected.is_null() {
                    assert_eq!(
                        result.reason,
                        case["error"].as_str().unwrap(),
                        "case {name}: expected an error"
                    );
                    assert_eq!(result.status, "withhold", "case {name}");
                } else {
                    let got = serde_json::json!({
                        "document_id": result.document_id,
                        "requested_package": result.requested_package,
                        "expected_package_pins": result.expected_package_pins,
                        "source_path": result.source_path,
                        "status": result.status,
                        "reason": result.reason,
                        "toc_class": result.toc_class,
                        "toc_title": result.toc_title,
                        "pages_1based": result.pages_1based,
                        "column_header": result.column_header,
                        "column_headers_all": result.column_headers_all,
                        "corroborating_jedec_ids": result.corroborating_jedec_ids,
                    });
                    assert_eq!(got, *expected, "case {name}");
                }
            }
            "classify_title" => {
                let got = classify_title(case["input"]["title"].as_str().unwrap());
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "package_pin_count" => {
                let got = package_pin_count(case["input"]["value"].as_str().unwrap());
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "match_package_column" => {
                let headers: Vec<String> = case["input"]["headers"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|h| h.as_str().unwrap().to_string())
                    .collect();
                let got =
                    match_package_column(case["input"]["requested"].as_str().unwrap(), &headers);
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "package_headers" => {
                let rows: Grid = serde_json::from_value(case["input"]["rows"].clone()).unwrap();
                let got = package_headers(&rows);
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "physical_truth" => {
                let pins: Vec<Value> = case["input"]["pins"].as_array().unwrap().clone();
                let outcome = validate_physical_pin_truth(
                    &pins,
                    case["input"]["package"].as_str().unwrap(),
                    case["input"]["expected_package_pins"].as_i64().unwrap(),
                );
                let expect = case["expected"].as_object().unwrap();
                let raised: Option<String> = outcome.as_ref().err().cloned();
                assert_eq!(
                    serde_json::to_value(&raised).unwrap(),
                    expect["raised"],
                    "case {name}: raised"
                );
            }
            "toc_entries" => {
                let toc: Vec<Value> = case["input"]["toc"].as_array().unwrap().clone();
                let got = toc_entries(&toc);
                let got: Vec<Value> = got
                    .iter()
                    .map(|e| serde_json::json!([e.level, e.title, e.page]))
                    .collect();
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
